describe('Item Details View', () => {
  beforeEach(() => {
    cy.visit('/items');
  });

  it('should display item details when clicking on an item card', () => {
    // Intercept the API call to fetch item details
    cy.intercept('GET', '/api/items/*').as('getItemDetails');

    // Verify item list is visible
    cy.get('[data-testid="item-list"]').should('be.visible');
    cy.get('[data-testid="item-card-1"]').should('be.visible');

    // Click on the first item card to view details
    cy.get('[data-testid="item-card-1"]').click();

    // Wait for the API call to complete
    cy.wait('@getItemDetails');

    // Verify item details page is displayed
    cy.get('[data-testid="item-details-page"]').should('be.visible');
    cy.get('[data-testid="item-title"]').should('contain', 'Product Name');
    cy.get('[data-testid="item-description"]').should('be.visible');
    cy.get('[data-testid="item-price"]').should('contain', '$19.99');
    cy.get('[data-testid="item-stock"]').should('contain', 'In Stock');

    // Verify back button is available
    cy.get('[data-testid="back-button"]').should('be.visible');
  });

  it('should handle item not found scenario when clicking on an item', () => {
    // Intercept the API call and return a 444 not found response
    cy.intercept('GET', '/api/items/999').as('getItemDetailsNotFound');

    // Navigate to items page
    cy.visit('/items');

    // Click on a non-existent item card
    cy.get('[data-testid="item-card-999"]').click();

    // Wait for the API call
    cy.wait('@getItemDetailsNotFound');

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Item not found');

    // Verify item details page is not displayed
    cy.get('[data-testid="item-details-page"]').should('not.exist');

    // Verify back button is still available
    cy.get('[data-testid="back-button"]').should('be.visible');
  });
});
